const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{
const p=await b.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(require('./island-test-helper.cjs'));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.click('#learningTab');await p.evaluate(()=>DEUTSCH_JOURNEY.select(0));
if(!await p.locator('#learningView.compact-island').count())throw Error('First island not compact');
if(await p.locator('.expedition-invitation').count())throw Error('Repeated invitation');
if(await p.locator('.compact-details').count()!==4)throw Error('Missing collapsed map collections');
for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Overflow '+width);await p.evaluate(()=>{const pins=[...document.querySelectorAll('.expedition-pin')];for(let i=0;i<pins.length;i++){const a=pins[i].getBoundingClientRect();for(let k=i+1;k<pins.length;k++){const c=pins[k].getBoundingClientRect();if(a.left<c.right&&a.right>c.left&&a.top<c.bottom&&a.bottom>c.top)throw Error('Pins overlap '+i+':'+k)}}});}
fs.mkdirSync('audit-screenshots',{recursive:true});await p.setViewportSize({width:390,height:1000});await p.screenshot({path:'audit-screenshots/compact-island1-map.png',fullPage:true});
for(const index of ['greetings',0,1,2,3,4,5,6,7]){await p.evaluate(index=>DEUTSCH_JOURNEY.open(index),index);if(!await p.locator('.al-study-grid').count())throw Error('Missing cards '+index);if(!await p.locator('.compact-details summary').filter({hasText:'Як це працює'}).count())throw Error('Missing training explanation '+index);const train=p.locator('#alContinue,#greetingBegin');if(!((await train.innerText()).includes('30')))throw Error('Wrong training label '+index);if(index===0)await p.screenshot({path:'audit-screenshots/compact-island1-lesson.png',fullPage:true});}
await p.evaluate(()=>{window.speak=()=>Promise.resolve();DEUTSCH_JOURNEY.open(0);document.querySelector('#alContinue').click();finishTrainingToTest();const a=DEUTSCH_ADAPTIVE;while(!a.snapshot().finished){const q=a.snapshot().queue[a.snapshot().index];a.answer(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}});
if(!await p.locator('[data-clue-new="true"]').count())throw Error('Clue missing');await p.screenshot({path:'audit-screenshots/compact-island1-result.png',fullPage:true});await p.click('#alDone');if(!await p.locator('.compact-details[open] .team-clues').count())throw Error('New clue hidden');
await p.evaluate(()=>DEUTSCH_JOURNEY.select(1));if(await p.locator('#learningView.compact-island,.compact-details').count())throw Error('Second island modified');if(!await p.locator('.expedition-invitation').count())throw Error('Village invitation removed');await p.evaluate(()=>DEUTSCH_JOURNEY.open(0));if((await p.locator('#alContinue').innerText())!=='Тренування')throw Error('Village lesson changed');
if(errors.length)throw Error(errors.join(';'));console.log('PASS compact island one: responsive pins, all nine intros, training/test reward, new clue expanded, island two unchanged');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
